using System;using System.IO;using System.Linq;using System.Text;using System.Threading;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Threading;
namespace FileCompass {
 internal static class EditorAnalyzerScreenshotTests {
  internal static int Run(string root){Directory.CreateDirectory(root);string language=L.Language;CodeEditorWindow editor=null;DiskAnalyzerWindow analyzer=null;MediaConverterWindow converter=null;try{SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(Dispatcher.CurrentDispatcher));FluentTheme.Ensure();string docs=Directory.CreateDirectory(Path.Combine(root,"Documents")).FullName;foreach(var item in new[]{Tuple.Create("Pictures\\Landscape.jpg",5000000),Tuple.Create("Pictures\\Portrait.jpg",2000000),Tuple.Create("Music\\Song.mp3",3000000),Tuple.Create("Videos\\Holiday.mp4",14000000),Tuple.Create("Reports\\Annual-report.pdf",1000000),Tuple.Create("Notes.txt",100000)}){string path=Path.Combine(docs,item.Item1);Directory.CreateDirectory(Path.GetDirectoryName(path));using(var output=File.Create(path))output.SetLength(item.Item2);}Directory.CreateDirectory(Path.Combine(docs,"Empty folder"));
   foreach(string locale in new[]{"cs","en"}){L.LoadForTests(AppPaths.Resource("languages"),locale);editor=new CodeEditorWindow(null){Left=-18000,Top=-18000,ShowActivated=false,WindowStartupLocation=WindowStartupLocation.Manual};editor.Show();var json=EditorTextFile.New();json.Path=@"D:\Example\Settings.json";json.Text="{\n  \"application\": \"Example\",\n  \"version\": 1,\n  \"items\": [\"Report.pdf\", \"Photo.jpg\"]\n}\n";editor.Add(json);var yaml=EditorTextFile.New();yaml.Path=@"D:\Example\Settings.yaml";yaml.Text="# Example configuration\napplication:\n  name: File Compass\n  language: en\n  appearance:\n    theme: light\n    fontSize: 14\n\nserver:\n  host: localhost\n  port: 8080\n  enabled: true\n\nfolders:\n  - Documents\n  - Pictures\n  - Music\n";editor.Add(yaml);NavigationTests.Wait(editor.Validate());editor.UpdateLayout();Draw(editor,Path.Combine(root,locale+".editor.png"),new[]{Tuple.Create((FrameworkElement)editor.EditorMenu.Items[0],new Point(42,22)),Tuple.Create((FrameworkElement)editor.EditorMenu.Items[1],new Point(42,22)),Tuple.Create((FrameworkElement)editor.EditorMenu.Items[2],new Point(42,22)),Tuple.Create((FrameworkElement)editor.EditorMenu.Items[3],new Point(42,22))});editor.Close();editor=null;
    converter=new MediaConverterWindow(null,new string[0],root,false,delegate{},delegate{}){Left=-18000,Top=-18000,ShowActivated=false,WindowStartupLocation=WindowStartupLocation.Manual};converter.Show();NavigationTests.Wait(converter.AnalysisTask);var audioInfo=new MediaInfo{Duration=7200};audioInfo.Audio.Add(new MediaTrack{Duration=7200,Index=0,Channels=2,SampleRate=48000,Codec="flac"});converter.Rows.Add(new MediaRow{Path=@"D:\Example\Soundtrack.flac",Image=false,Info=audioInfo,Summary=audioInfo.Summary,Status=L.Text("media.ready")});converter.SettingsTabs.SelectedItem=converter.SpeedTab;converter.SpeedPreset.SelectedIndex=13;converter.TargetLength.Text="01:55:00.000";converter.Folder.Text=@"D:\Example\Converted";converter.UpdateLayout();Draw(converter,Path.Combine(root,locale+".audio-speed.png"),new[]{Tuple.Create((FrameworkElement)converter.SpeedPreset,new Point(240,25)),Tuple.Create((FrameworkElement)converter.SpeedPercent,new Point(240,25)),Tuple.Create((FrameworkElement)converter.TargetLength,new Point(240,25)),Tuple.Create((FrameworkElement)converter.SpeedMethod,new Point(240,25))});converter.Close();converter=null;
    analyzer=new DiskAnalyzerWindow(null,docs,null,true){Left=-18000,Top=-18000,ShowActivated=false,WindowStartupLocation=WindowStartupLocation.Manual};analyzer.Show();NavigationTests.Wait(analyzer.ScanTask);analyzer.ChartChoice.SelectedIndex=2;NavigationTests.Wait(analyzer.MapLoadingTask);analyzer.DrawHelpDemo(root);Draw(analyzer,Path.Combine(root,locale+".analyzer.png"),new[]{Tuple.Create((FrameworkElement)analyzer.AnalyzerPages,new Point(145,20)),Tuple.Create((FrameworkElement)analyzer.ShareChoice,new Point(analyzer.ShareChoice.ActualWidth-8,22)),Tuple.Create((FrameworkElement)analyzer.ChartChoice,new Point(analyzer.ChartChoice.ActualWidth-8,22)),Tuple.Create((FrameworkElement)analyzer.Chart,new Point(analyzer.Chart.ActualWidth-18,18)),Tuple.Create((FrameworkElement)analyzer.AnalyzerPages,new Point(275,20))});analyzer.Close();analyzer=null;
   }File.WriteAllText(Path.Combine(root,"result.txt"),"PASS: Czech and English editor/analyzer screenshots use generated demonstration files and generic paths.");return 0;
  }catch(Exception ex){File.WriteAllText(Path.Combine(root,"result.txt"),"FAIL: "+ex);return 1;}finally{if(editor!=null)editor.Close();if(converter!=null)converter.Close();if(analyzer!=null)analyzer.Close();L.LoadForTests(AppPaths.Resource("languages"),language);}}
  static void Draw(Window window,string path,Tuple<FrameworkElement,Point>[] markers){window.UpdateLayout();var content=(FrameworkElement)window.Content;int width=(int)Math.Ceiling(content.ActualWidth+content.Margin.Left+content.Margin.Right),height=(int)Math.Ceiling(content.ActualHeight+content.Margin.Top+content.Margin.Bottom);var bitmap=new RenderTargetBitmap(width,height,96,96,PixelFormats.Pbgra32);var backdrop=new DrawingVisual();using(var dc=backdrop.RenderOpen())dc.DrawRectangle(window.Background,null,new Rect(0,0,width,height));bitmap.Render(backdrop);bitmap.Render(content);var overlay=new DrawingVisual();using(var dc=overlay.RenderOpen()){for(int i=0;i<markers.Length;i++){var position=markers[i].Item1.TranslatePoint(markers[i].Item2,content);dc.DrawEllipse(Brushes.RoyalBlue,new Pen(Brushes.White,2),position,11,11);var text=new FormattedText((i+1).ToString(),System.Globalization.CultureInfo.InvariantCulture,FlowDirection.LeftToRight,new Typeface("Segoe UI Semibold"),12,Brushes.White,1);dc.DrawText(text,new Point(position.X-text.Width/2,position.Y-text.Height/2));}}bitmap.Render(overlay);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var output=File.Create(path))encoder.Save(output);}
 }
}
